import {
  MainWrapper,
  ContentWrapper,
  ProjectModule,
  Image,
  ProjectContentWrapper,
  Button
} from "./index.stitches";
import data from "../../data/project.json";

console.log(data);

function ProjectGrid() {
  return (
    <MainWrapper>
      <ContentWrapper>
        {data.map((item, i) => {
          return (
            <ProjectModule key={i}>
              <Image />
              <ProjectContentWrapper>
                <p>{i}/{data.length}</p>
                <p>{item[0]}</p>
                <Button>Link to story</Button>
                <p>{item[2]}</p>
              </ProjectContentWrapper>
            </ProjectModule>
          );
        })}
      </ContentWrapper>
    </MainWrapper>
  );
}

export default ProjectGrid;
